 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == frame:
        panel_w += 1
    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    panels = []
    for top, bottom in zip(separators, separators[1:]):
        holes = {(r-top-1, c-1) for r in range(top+1, bottom) for c in range(1, panel_w-1) if grid[r][c] == 0}
        if holes:
            max_r = max(r for r, c in holes)
            max_c = max(c for r, c in holes)
            sig = frozenset(holes)
            panels.append((top, bottom, max_r+1, max_c+1, sig))
    seen = set()
    objects = {}
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and panel_w <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            r0 = min(a for a,b in cells); c0 = min(b for a,b in cells)
            shape = frozenset((a-r0,b-c0) for a,b in cells)
            objects.setdefault((max(a for a,b in shape)+1, max(b for a,b in shape)+1, shape), color)
    out = [row[:panel_w] for row in grid]
    for top, bottom, ph, pw, sig in panels:
        color = objects.get((ph, pw, sig))
        if color is not None:
            for rr, cc in sig:
                out[top+1+rr][1+cc] = color
    return out
"
